(()=>{
'use strict';const $=s=>document.querySelector(s),core=window.ExponentialLesson,num=window.LinearLesson,ns='http://www.w3.org/2000/svg';
function math(host,tex){const e=document.createElement('span');e.dataset.tex=tex;host.replaceChildren(e);}
function fraction(q){return num.fractionTex(num.rational(q.n,q.d));}
function baseTex(key){const b=core.bases[key];return b.d===1?String(b.n):`\\left(${fraction(b)}\\right)`;}
$('#comparison-table').innerHTML=Array.from({length:6},(_,x)=>`<tr><th scope="row"><span data-tex="${x}"></span></th><td><span data-tex="${1+2*x}"></span></td><td><span data-tex="${2**x}"></span></td></tr>`).join('');
function svg(tag,attrs,parent){const e=document.createElementNS(ns,tag);for(const [k,v] of Object.entries(attrs))e.setAttribute(k,v);parent.append(e);}
function tick(n,left,top){const e=document.createElement('span');e.className='expo-tick';e.dataset.noEquation='';e.textContent=String(n).replace('-','−');e.style.left=left+'%';e.style.top=top+'%';$('#expo-ticks').append(e);}
for(let x=-3;x<=3;x++){const p=core.point(x,0);svg('line',{x1:p.x,x2:p.x,y1:50,y2:310},$('#expo-grid'));tick(x,p.x/3.6,90);}
for(let y=2;y<=10;y+=2){const p=core.point(0,y);svg('line',{x1:40,x2:320,y1:p.y,y2:p.y},$('#expo-grid'));tick(y,47,p.y/3.6);}
function draw(){const A=Number($('#initial-value').value),key=$('[name="expo-base"]:checked').value,x=Number($('#expo-input').value),b=core.bases[key],result=core.exact(A,key,x),p=core.point(x,result.n/result.d),initial=core.point(0,A);$('#initial-output').value=A;$('#expo-input-output').value=x;const commands=[];for(let i=0;i<=240;i++){const u=-3+i/40,q=core.point(u,core.value(A,key,u));commands.push(`${i===0?'M':'L'}${q.x} ${q.y}`);}$('#expo-curve').setAttribute('d',commands.join(' '));$('#expo-dot').setAttribute('cx',p.x);$('#expo-dot').setAttribute('cy',p.y);$('#initial-dot').setAttribute('cx',initial.x);$('#initial-dot').setAttribute('cy',initial.y);const multiplier=A===1?'':A+'\\cdot';math($('#expo-equation'),`f(x)=${multiplier}${baseTex(key)}^x`);math($('#expo-evaluation'),`f(${x})=${multiplier}${baseTex(key)}^{${x}}=${fraction(result)}`);math($('#ratio-summary'),`\\frac{f(x+1)}{f(x)}=${fraction(b)}`);$('#expo-table').innerHTML=Array.from({length:6},(_,i)=>i-2).map(u=>`<tr class="${u===x?'selected':''}" ${u===x?'aria-current="true"':''}><th scope="row"><span data-tex="${u}"></span></th><td><span data-tex="${fraction(core.exact(A,key,u))}"></span></td></tr>`).join('');$('#expo-feedback').innerHTML=(b.n>b.d?'Basis lebih dari satu: fungsi meningkat ketika masukan bertambah.':'Basis positif kurang dari satu: fungsi menurun ketika masukan bertambah.')+` Nilai pada masukan nol adalah <span data-tex="${A}"></span>. `+(result.n/result.d>10?'Titik yang dipilih berada di atas jendela grafik; nilai tepatnya tetap ditampilkan pada rumus dan tabel.':x===0?'Titik yang dipilih berimpit dengan titik nilai awal.':'Keluaran tetap positif, termasuk ketika masukan negatif.')+' Seluruh kurva mempunyai domain bilangan real dan range bilangan real positif.';$('#expo-plot').setAttribute('aria-label',`Fungsi eksponensial dengan nilai awal ${A}, basis ${b.n} dibagi ${b.d}. ${b.n>b.d?'Meningkat':'Menurun'}. Masukan terpilih ${x}, keluaran ${result.n} dibagi ${result.d}. Asimtot mendatar y sama dengan nol.`);}
['initial-value','expo-input'].forEach(id=>$('#'+id).addEventListener('input',draw));document.querySelectorAll('[name="expo-base"]').forEach(e=>e.addEventListener('change',draw));$('#reset-expo').addEventListener('click',()=>{$('#initial-value').value=1;$('#expo-input').value=1;$('[name="expo-base"][value="two"]').checked=true;draw();});draw();
const questions=[{tex:'f(x)=3\\cdot2^x',prompt:'Berapa keluaran untuk masukan negatif dua?',n:3,d:4,hint:'Dua berpangkat negatif dua adalah seperempat, lalu kalikan tiga.',why:'Pangkat negatif memberi kebalikan pangkat positif. Tiga dikali seperempat menghasilkan tiga perempat, bukan bilangan negatif.'},{tex:'N(t)=100(0{,}8)^t',prompt:'Berapa nilai setelah dua periode?',n:64,d:1,hint:'Kalikan nilai awal dengan delapan persepuluh dua kali.',why:'Seratus menjadi delapan puluh pada periode pertama dan enam puluh empat pada periode kedua. Pengurangannya bukan jumlah tetap.'},{tex:'N(t)=100(1{,}1)^t',prompt:'Berapa nilai setelah dua periode?',n:121,d:1,hint:'Persentase periode kedua dihitung dari nilai terbaru, yaitu seratus sepuluh.',why:'Seratus sepuluh dikalikan satu koma satu menghasilkan seratus dua puluh satu, bukan seratus dua puluh.'}];const solved=new Set();function report(i,ok,text){const e=$('#feedback'+i);e.className='feedback '+(ok?'correct':'incorrect');e.textContent=text;if(ok)solved.add(i);$('#progress').textContent=`${solved.size} dari 6 latihan sudah dijawab tepat.`;}
$('#questions').innerHTML=questions.map((q,i)=>`<div class="question"><h3 data-no-equation>Latihan ${i+1}</h3><p data-tex="${q.tex}"></p><p>${q.prompt}</p><form data-question="${i}"><label for="answer${i}">Jawabanmu</label><div class="answer-line"><input id="answer${i}" type="text" required autocomplete="off" aria-describedby="feedback${i}"><button class="button" type="submit">Periksa jawaban</button></div></form><p class="feedback" id="feedback${i}" role="status"></p><details><summary>Butuh petunjuk?</summary><p>${q.hint}</p></details><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details></div>`).join('');document.querySelectorAll('form[data-question]').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();const i=Number(form.dataset.question),q=questions[i],a=num.parseAnswer($('#answer'+i).value),ok=num.equalAnswer(a,num.rational(q.n,q.d));report(i,ok,ok?'Tepat. '+q.why:!a?'Tulis satu bilangan, misalnya 3/4 atau 0,75.':'Belum tepat. Periksa makna pangkat dan faktor perkalian setiap periode.');}));
const choices=[{tex:'f(x)=2^x,\\qquad g(x)=x^2',prompt:'Pernyataan mana yang membedakan kedua fungsi ini?',options:['Keduanya eksponensial karena mengandung pangkat.','Fungsi pertama eksponensial; fungsi kedua adalah fungsi pangkat.','Fungsi kedua eksponensial karena nilai keluarannya dapat membesar.'],answer:1,why:'Pada fungsi pertama, variabel berada pada pangkat dan basisnya tetap. Pada fungsi kedua, variabel adalah basis dengan pangkat tetap.'},{tex:'f(x)=\\left(\\frac12\\right)^x',prompt:'Bagaimana perubahan keluaran ketika masukan bertambah satu?',options:['Keluaran menjadi setengah nilai sebelumnya.','Keluaran selalu berkurang setengah satuan.','Keluaran menjadi dua kali nilai sebelumnya.'],answer:0,why:'Basis setengah berarti faktor perkaliannya setengah untuk setiap kenaikan satu pada masukan. Selisih keluarannya tidak tetap.'},{tex:'f(x)=2^x,\\quad D=\\mathbb R',prompt:'Apa range fungsi ini?',options:['Semua bilangan real.','Semua bilangan real tidak negatif, termasuk nol.','Semua bilangan real positif, tanpa nol.'],answer:2,why:'Keluaran selalu positif. Fungsi dapat mendekati nol tetapi tidak mencapainya; setiap bilangan real positif dapat dicapai.'}];for(let j=0;j<choices.length;j++){const i=j+3,q=choices[j],box=document.createElement('div');box.className='question';box.innerHTML=`<h3 data-no-equation>Latihan ${i+1}</h3><p data-tex="${q.tex}"></p><fieldset><legend>${q.prompt}</legend>${q.options.map((o,k)=>`<label class="choice"><input type="radio" name="choice${i}" value="${k}">${o}</label>`).join('')}</fieldset><button type="button" class="button" data-check="${i}">Periksa jawaban</button><p class="feedback" id="feedback${i}" role="status"></p><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details>`;$('#questions').append(box);box.querySelector('button').addEventListener('click',()=>{const a=$(`[name="choice${i}"]:checked`),ok=!!a&&Number(a.value)===q.answer;report(i,ok,!a?'Pilih jawaban dahulu.':(ok?'Tepat. ':'Belum tepat. ')+q.why);});}
const storage={get(k){try{return localStorage.getItem('fondasi-exponential-'+k)}catch{return null}},set(k,v){try{localStorage.setItem('fondasi-exponential-'+k,v);return true}catch{return false}}};$('#reflection').value=storage.get('reflection')||'';$('#reflection').addEventListener('input',()=>{$('#save-note').textContent=storage.set('reflection',$('#reflection').value)?'Catatan tersimpan di peramban ini.':'Catatan belum dapat disimpan; salin jika diperlukan.';});function complete(saved){$('#complete').textContent='Bacaan sudah ditandai selesai ✓';$('#complete-note').textContent=saved?'Kemajuan tersimpan di peramban ini. Kamu bisa mencoba kembali kapan saja.':'Bacaan selesai; kemajuan belum dapat disimpan di peramban ini.';}$('#complete').addEventListener('click',()=>complete(storage.set('complete','yes')));if(storage.get('complete')==='yes')complete(true);
})();